mapper.select:
SELECT NOTIFICATION_ID AS notificationId, USER_ID AS userId, NOTIFICATION_TYPE AS notificationType, NOTIFICATION_TITLE AS notificationTitle, NOTIFICATION_CONTENT AS notificationContent, NOTIFICATION_URL AS notificationUrl, IS_READ AS isRead, NOTIFICATION_CREATED_AT AS notificationCreatedAt FROM NOTIFICATION WHERE USER_ID = #{userId}
AND IS_READ = FALSE
ORDER BY NOTIFICATION_CREATED_AT DESC

SELECT EXISTS(
  SELECT 1
    FROM NOTIFICATION
   WHERE USER_ID = #{userId}
     AND IS_READ = FALSE
)

SELECT USER_ID
FROM NOTIFICATION
WHERE NOTIFICATION_ID = #{notificationId}

mapper.update:
UPDATE NOTIFICATION
SET IS_READ = TRUE
WHERE NOTIFICATION_ID = #{notificationId}
